export class Camera { constructor(width, height, level) { Object.assign(this, { x: 0, y: 0, width, height, level }); } follow(target) { this.x += (target.x + target.w / 2 - this.width / 2 - this.x) * 0.12; this.y += (target.y + target.h / 2 - this.height / 2 - this.y) * 0.08; this.x = Math.max(0, Math.min(this.level.width - this.width, this.x)); this.y = Math.max(0, Math.min(this.level.height - this.height, this.y)); } }
